/*
  Add the JP workbook's second material block (frame rows 35-43).

  Source: JS,JP,JA,JE,JK,JM计算表.xlsx / JP sheet.  The existing unified
  migration stops at row 26, so the runtime omitted frame weight and used the
  first block's one-sided area instead of the workbook's final V3 total.
*/
BEGIN;

CREATE TEMP TABLE desired_jp_frame_rule (
  source_row_no INTEGER PRIMARY KEY,
  raw_rule JSONB NOT NULL
) ON COMMIT DROP;

INSERT INTO desired_jp_frame_rule VALUES
  (35, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (36, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (37, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (38, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (39, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (40, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (41, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (42, convert_from(decode('', 'hex'), 'UTF8')::jsonb),
  (43, convert_from(decode('', 'hex'), 'UTF8')::jsonb);

/*
  Excel evaluates IF branches lazily, while the recovered V3 evaluator is
  eager.  Make the two JP quantity formulas algebraically equivalent but safe
  when the workbook default B15 is zero.
*/
UPDATE desired_jp_frame_rule
SET raw_rule = jsonb_set(
  raw_rule,
  '{formulas,8}',
  to_jsonb(
    CASE source_row_no
      WHEN 42 THEN '=IF(AND($B$23=1,$B$14=1,$B$25=0),$B$9-$B$15,IF(AND($B$23=1,$B$14=1,$B$25=1),2*$B$9-$B$15,$B$9*$B$23))'
      WHEN 43 THEN '=IF(AND($B$14=1,$B$9<>1),($B$9-$B$15)*4,)'
    END
  ),
  false
)
WHERE source_row_no IN (42, 43);

DO $assert$
DECLARE missing_templates TEXT;
BEGIN
  SELECT string_agg(code, ', ' ORDER BY code) INTO missing_templates
  FROM (VALUES ('JP_SINGLE'), ('JP_DOUBLE')) AS wanted(code)
  LEFT JOIN calc.cabinet_template t ON t.template_code = wanted.code
  WHERE t.template_id IS NULL;
  IF missing_templates IS NOT NULL THEN
    RAISE EXCEPTION 'Missing JP formula templates: %', missing_templates;
  END IF;
END;
$assert$;

UPDATE calc.cabinet_part_rule r
SET part_name = COALESCE(d.raw_rule->'values'->>1, ''),
    condition_formula = NULLIF(d.raw_rule->'formulas'->>22, ''),
    length_formula = NULLIF(d.raw_rule->'formulas'->>2, ''),
    width_formula = NULLIF(d.raw_rule->'formulas'->>3, ''),
    thickness_formula = NULLIF(d.raw_rule->'formulas'->>4, ''),
    density_formula = NULLIF(d.raw_rule->'formulas'->>5, ''),
    single_quantity_formula = NULLIF(d.raw_rule->'formulas'->>7, ''),
    total_quantity_formula = NULLIF(d.raw_rule->'formulas'->>8, ''),
    weight_formula = NULLIF(d.raw_rule->'formulas'->>9, ''),
    area_formula = NULLIF(d.raw_rule->'formulas'->>21, ''),
    surface_treatment = COALESCE(
      NULLIF(d.raw_rule->'formulas'->>10, ''),
      NULLIF(d.raw_rule->'values'->>10, '')
    ),
    include_material_cost = TRUE,
    include_spray_area = TRUE,
    sort_no = d.source_row_no,
    raw_rule = d.raw_rule
FROM calc.cabinet_template t
CROSS JOIN desired_jp_frame_rule d
WHERE r.template_id = t.template_id
  AND t.template_code IN ('JP_SINGLE', 'JP_DOUBLE')
  AND r.source_row_no = d.source_row_no;

WITH seed AS (
  SELECT DISTINCT ON (t.template_code)
         t.template_code,
         t.template_id AS target_template_id,
         r.material_id AS seed_material_id,
         r.process_route AS seed_process_route,
         r.is_purchasable AS seed_is_purchasable
  FROM calc.cabinet_template t
  JOIN calc.cabinet_part_rule r ON r.template_id = t.template_id
  WHERE t.template_code IN ('JP_SINGLE', 'JP_DOUBLE')
  ORDER BY t.template_code, r.sort_no, r.source_row_no, r.rule_id
)
INSERT INTO calc.cabinet_part_rule (
  template_id, part_code, part_name, material_id, condition_formula,
  length_formula, width_formula, thickness_formula, density_formula,
  single_quantity_formula, total_quantity_formula, weight_formula, area_formula,
  surface_treatment, process_route, is_purchasable,
  include_material_cost, include_spray_area, sort_no, source_row_no, raw_rule
)
SELECT s.target_template_id,
       concat(s.template_code, '_FRAME_', d.source_row_no),
       COALESCE(d.raw_rule->'values'->>1, ''),
       s.seed_material_id,
       NULLIF(d.raw_rule->'formulas'->>22, ''),
       NULLIF(d.raw_rule->'formulas'->>2, ''),
       NULLIF(d.raw_rule->'formulas'->>3, ''),
       NULLIF(d.raw_rule->'formulas'->>4, ''),
       NULLIF(d.raw_rule->'formulas'->>5, ''),
       NULLIF(d.raw_rule->'formulas'->>7, ''),
       NULLIF(d.raw_rule->'formulas'->>8, ''),
       NULLIF(d.raw_rule->'formulas'->>9, ''),
       NULLIF(d.raw_rule->'formulas'->>21, ''),
       COALESCE(
         NULLIF(d.raw_rule->'formulas'->>10, ''),
         NULLIF(d.raw_rule->'values'->>10, '')
       ),
       s.seed_process_route, s.seed_is_purchasable,
       TRUE, TRUE, d.source_row_no, d.source_row_no, d.raw_rule
FROM seed s
CROSS JOIN desired_jp_frame_rule d
WHERE NOT EXISTS (
  SELECT 1 FROM calc.cabinet_part_rule existing
  WHERE existing.template_id = s.target_template_id
    AND existing.source_row_no = d.source_row_no
);

UPDATE calc.template_formula_mapping
SET notes = concat_ws(
      '; ', NULLIF(notes, ''),
      '2026-08-28 include JP frame rows 35-43; final runtime area is rows 5-43 / 2'
    )
WHERE template_code IN ('JP_SINGLE', 'JP_DOUBLE')
  AND COALESCE(notes, '') NOT LIKE '%include JP frame rows 35-43%';

DO $verify$
DECLARE mismatch TEXT;
BEGIN
  SELECT string_agg(
           format('%s has %s of 9 JP frame rows', failed.template_code, failed.frame_rule_count),
           '; '
         )
    INTO mismatch
  FROM (
    SELECT t.template_code, count(r.rule_id) AS frame_rule_count
    FROM calc.cabinet_template t
    LEFT JOIN calc.cabinet_part_rule r
      ON r.template_id = t.template_id AND r.source_row_no BETWEEN 35 AND 43
    WHERE t.template_code IN ('JP_SINGLE', 'JP_DOUBLE')
    GROUP BY t.template_code
    HAVING count(r.rule_id) <> 9
  ) AS failed;
  IF mismatch IS NOT NULL THEN
    RAISE EXCEPTION 'JP frame formula migration mismatch: %', mismatch;
  END IF;
END;
$verify$;

COMMIT;
